update public.products set description='Whole turkey is a large poultry bird with generous breast, thigh, leg and wing portions, suitable for roasting, grilling, smoking or portioning for soups and stews.', handling_protocols=array['Keep raw turkey separated from cooked foods, vegetables and other ready-to-eat foods.','Do not wash raw turkey; clean hands, utensils and surfaces after handling.','Thaw frozen turkey in the refrigerator, cold water while securely wrapped, or by microwave followed by immediate cooking; never thaw on a counter.','Cook the innermost thigh, innermost wing and thickest breast to at least 74°C / 165°F.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','If frozen, keep at about -18°C or below and use within about 6–12 months for best quality.','Allow several days for a large whole turkey to thaw safely in the refrigerator.']::text[] where name='Whole Turkey' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Turkey wings are large bone-in poultry portions with meat and skin, suitable for roasting, grilling, frying, soups, stews and slow-cooked dishes.', handling_protocols=array['Treat as raw poultry and keep cold and separated from ready-to-eat foods.','Do not wash raw turkey; clean hands and preparation surfaces after handling.','Cook the thickest part to at least 74°C / 165°F without measuring directly against the bone.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','If frozen, keep at about -18°C or below and use within about 6–9 months for best quality.','After refrigerator thawing, cook within 1–2 days.']::text[] where name='Turkey Wings' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
